// a face for a speaker in the read-aloud lines, one colour per speaker
const FACE_TOPS = ['#8E5BC6', '#2E86DE', '#F28C28', '#16A085', '#E5534B'];
function face(i) {
  const top = FACE_TOPS[i % FACE_TOPS.length];
  return `<svg class="qface" viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="20" fill="${top}" opacity=".18"/>`
    + `<path d="M7 40c1-9 6-13 13-13s12 4 13 13z" fill="${top}"/><circle cx="20" cy="17" r="9" fill="#D9A07A"/>`
    + `<path d="M11 15c0-6 4-9 9-9s9 3 9 9c-2-3-5-4-9-4s-7 1-9 4z" fill="#2B2521"/>`
    + '<circle cx="17" cy="17" r="1.2" fill="#2B2521"/><circle cx="23" cy="17" r="1.2" fill="#2B2521"/><path d="M17 21c2 1.5 4 1.5 6 0" stroke="#7A2E2E" stroke-width="1.3" fill="none" stroke-linecap="round"/></svg>';
}

const DRAW = { clock, clock_pair: clockPair, tiles, blender, blender_list: blenderList, blend_steps: blendSteps, scene, predict, dictionary };
// the visual types drawn as HTML by primary.js rather than as SVG here
const HTML_VISUALS = ['story_map', 'tracker'];
function draw(spec) {
  if (!spec || !spec.type) return '';
  const f = DRAW[spec.type];
  if (!f) throw new Error(`no drawing for visual type "${spec.type}"`);
  return f(spec);
}

module.exports = { draw, DRAW, HTML_VISUALS, heroBadge, ICON, face, parseTime, C };
